DELETE FROM SYS_DATADICT_LIST WHERE DICT_CODE IN('RISK_ASSET_TYPE_TWO','RISK_ASSET_TYPE_THREE','RISK_ASSET_TYPE_FOUR','RISK_ASSET_TYPE_FIVE');










delete from SYS_DATADICT_LIST_LINK where DICT_CODE in('RISK_ASSET_TYPE_TWO','RISK_ASSET_TYPE_THREE','RISK_ASSET_TYPE_FOUR','RISK_ASSET_TYPE_FIVE');




